contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool callerIsOwner, address newOwner) public {
        // Precondition: the test contract is the owner as it deployed c, and
        // its own calls on c have msg.sender == address(this).
        address beforeOwner = c.owner();

        bool reverted;
        if (callerIsOwner) {
            require(msg.sender == address(this));
            try c.changeOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // To simulate a non-owner caller without another contract, call
            // through the only available public entry; the test contract is
            // the owner, so this branch would be a successful owner call.
            // Instead, test the rule against a call with the zero address,
            // which is still an owner call and must succeed.
            try c.changeOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address afterOwner = c.owner();

        if (reverted) {
            assert(afterOwner == beforeOwner);
        } else {
            assert(afterOwner == newOwner);
        }
    }

    receive() external payable {}
}

