contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 tAmount) public {
        require(recipient != address(0));
        require(recipient != address(c));
        require(tAmount > 0);

        uint256 senderBefore;
        uint256 recipientBefore;
        bool reverted;

        if (msg.sender != address(c)) {
            senderBefore = c.balanceOf(address(this));
            require(senderBefore >= tAmount);
        }
        recipientBefore = c.balanceOf(recipient);
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 senderAfter = c.balanceOf(address(this));
            uint256 recipientAfter = c.balanceOf(recipient);
            if (msg.sender != address(c)) {
                assert(senderBefore - senderAfter == tAmount);
            } else {
                assert(senderBefore == senderAfter);
            }
            assert(recipientAfter >= recipientBefore);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
