    }

    function run(address recipient, uint256 tAmount) public {
        require(recipient != address(0));
        require(recipient != address(c));
        require(tAmount > 0);
        require(msg.sender != address(c));

        uint256 senderBefore = c.balanceOf(address(this));
        require(senderBefore >= tAmount);
        uint256 recipientBefore = c.balanceOf(recipient);

        bool ok;
        bool reverted;
        try c.transfer(recipient, tAmount) returns (bool r) { ok = r; reverted = false; } catch { reverted = true; }

        uint256 recipientAfter = c.balanceOf(recipient);

        assert(!reverted && ok && (address(this) == recipient ? recipientAfter == recipientBefore : recipientAfter >= recipientBefore + tAmount));
    }

    receive() external payable {}
}

