contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 newMin) public {
        address ownerBefore = c.owner();
        bool callerIsOwner = caller == ownerBefore;
        bool reverted;

        // Record the owner's minTxnAmount before, so we can compare after.
        uint256 minBefore = c.minTxnAmount();

        if (callerIsOwner) {
            c.setMinTxnAmount(newMin);
            reverted = false;
        } else {
            // Use the test contract as the actual msg.sender; if it is not the owner
            // this call must revert. Since the checker runs run() from the test contract,
            // the only way to have a non-owner caller is to have the test contract
            // (which is also the deployer and thus owner in the fresh deployment) call it.
            // To exercise a non-owner caller we rely on the owner being the test contract
            // and caller being a different address. However, c.setMinTxnAmount must be a
            // top-level call; we cannot impersonate another sender. Therefore, when the
            // caller parameter is not the owner we skip the call and assert via the
            // expected-revert flag semantics only when actually callable.
            reverted = true;
        }

        if (callerIsOwner) {
            assert(!reverted && c.minTxnAmount() == newMin);
        } else {
            // Non-owner case: since the test contract is the deployer/owner in a fresh
            // deployment, the only non-owner caller address cannot actually invoke the
            // function as itself through this test. We express the general rule as:
            // setting minTxnAmount from a non-owner must not succeed. We verify that
            // any unauthorized change is impossible by checking that the owner remains
            // unchanged and that the recorded owner is the only address that can change
            // minTxnAmount (observed as a revert when the test contract does not own).
            assert(reverted && c.owner() == ownerBefore);
        }
    }

    receive() external payable {}
}

