contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        address ownerBefore = c.owner();

        if (caller == ownerBefore) {
            // owner call must succeed
            (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("changeOwner(address)", newOwner));
            require(ok, "owner changeOwner reverted");
            // silence unused warning
            ret;
            assert(c.owner() == newOwner);
        } else {
            // non-owner call must revert and owner must remain unchanged
            (bool ok, ) = address(c).call(abi.encodeWithSignature("changeOwner(address)", newOwner));
            assert(!ok && c.owner() == ownerBefore);
        }
    }

    receive() external payable {}
}

