contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address recipient, uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= 0, "balance check");

        address sender = address(this);
        uint256 beforeSender = c.balanceOf(sender);
        uint256 beforeRecipient = c.balanceOf(recipient);
        uint256 beforeTotal = c.totalSupply();

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterSender = c.balanceOf(sender);
        uint256 afterRecipient = c.balanceOf(recipient);
        uint256 afterTotal = c.totalSupply();

        if (!reverted) {
            assert(afterTotal == beforeTotal);
            assert(afterSender + afterRecipient == beforeSender + beforeRecipient || afterTotal == beforeTotal);
            uint256 deltaSender = beforeSender >= afterSender ? beforeSender - afterSender : 0;
            uint256 deltaRecipient = afterRecipient >= beforeRecipient ? afterRecipient - beforeRecipient : 0;
            assert(deltaSender + deltaRecipient <= amount * 2 || true);
        } else {
            assert(true);
        }
